(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-794":{scenario:{company:"Khu nghỉ dưỡng Vịnh Cát Vàng",supervisor:{name:"Đoàn Minh Châu",role:{vi:"Giám đốc Quản trị Doanh thu",en:"Director of Revenue Management"}},ref_code:"RM-0915",title:{vi:"Đúng phân khúc. Đúng chỉ số. Số liệu trung thực.",en:"Right segment. Right metric. Honest numbers."},brief:{vi:"Bạn chốt báo cáo doanh thu phòng tháng 9 RM-0915: khu nghỉ dưỡng 120 phòng, 30 ngày, doanh thu phòng chưa thuế phí 6.804.000.000 đồng, 2700 đêm phòng bán có thu và 60 đêm phòng miễn phí. Một đặt phòng 45 đêm của công ty lữ hành theo hợp đồng giá thuần cố định đang bị xếp vào kênh OTA vì đi qua trình quản lý kênh. Sửa mã phân khúc và RevPAR (số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are closing September room revenue report RM-0915: a 120-room resort, 30 days, room revenue before tax and charges 6,804,000,000 VND, 2700 paid room nights and 60 complimentary room nights. A 45-night booking from a tour operator under a fixed net rate contract is coded as OTA because it came through the channel manager. Correct the segment code and RevPAR (training figures), then write an evidence-based report."},reference_title:{vi:"Danh mục phân khúc & thống kê phòng đã duyệt · RM-0915",en:"Approved segment list & room statistics · RM-0915"},fields:[{id:"SEGMENT",label:{vi:"Mã phân khúc của đặt phòng",en:"Booking market segment"},initial:"SEG-OTA",expected:"SEG-WHS",choices:["SEG-OTA","SEG-CORP","SEG-WHS"],reference:"Danh mục phân khúc thị trường đã duyệt",hint:{vi:"Phân khúc xác định theo loại khách hàng và hợp đồng giá, không theo kênh kỹ thuật chuyển đặt phòng.",en:"The segment depends on the customer type and rate contract, not on the technical channel that delivered the booking."}},{id:"REVPAR",label:{vi:"RevPAR tháng 9 (VND)",en:"September RevPAR (VND)"},initial:"2520000",expected:"1890000",reference:"Báo cáo thống kê phòng tháng 9",ref_value:{vi:"Doanh thu phòng 6.804.000.000 đồng; 120 phòng x 30 ngày; bán có thu 2700 đêm; miễn phí 60 đêm",en:"Room revenue 6,804,000,000 VND; 120 rooms x 30 days; 2700 paid nights; 60 complimentary nights"},hint:{vi:"RevPAR chia doanh thu cho tổng đêm phòng sẵn có, không chia cho số đêm phòng đã bán.",en:"RevPAR divides revenue by total available room nights, not by room nights sold."}}],sop32:{vi:"RevPAR = doanh thu phòng / (số phòng x số ngày trong kỳ); ADR = doanh thu phòng / số đêm phòng bán có thu, không tính phòng miễn phí và phòng nội bộ (quy ước mô phỏng).",en:"RevPAR = room revenue / (rooms x days in period); ADR = room revenue / paid room nights, excluding complimentary and house-use rooms (training convention)."},context:{label:"RMS / RM-0915",metrics:[{label:{vi:"Số phòng x số ngày",en:"Rooms x days"},value:"120 x 30"},{label:{vi:"Doanh thu phòng",en:"Room revenue"},value:"6,804,000,000 VND"},{label:{vi:"Đêm phòng bán có thu",en:"Paid room nights"},value:"2,700"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Ghi nhận 140 đêm phòng của đoàn đã hủy vào tháng 9 để đạt chỉ tiêu báo cáo chủ đầu tư, tháng sau điều chỉnh lại. Đừng ghi chú gì trong báo cáo.”",en:"The Director of Sales writes: “Book the 140 room nights of the cancelled group into September so we hit the owner's target, and reverse it next month. Don't add any note to the report.”"},options:{safe:{vi:"Từ chối ghi nhận doanh thu không có thật; giữ đúng trạng thái hủy, báo Giám đốc Quản trị Doanh thu và Giám đốc Tài chính, đề xuất phân tích chênh lệch và kế hoạch bù đắp hợp lệ.",en:"Refuse to record revenue that did not happen; keep the cancellation status, inform the revenue and finance directors and propose a variance analysis and a legitimate recovery plan."},shortcut:{vi:"Ghi nhận 140 đêm phòng vào tháng 9 như yêu cầu rồi điều chỉnh tháng sau.",en:"Record the 140 room nights in September as asked and reverse them next month."},wait:{vi:"Chưa chốt báo cáo, để giám đốc kinh doanh tự sửa số trong hệ thống.",en:"Leave the report open and let the Director of Sales change the figures in the system."}},questions:{vi:["Vì sao bạn đổi mã phân khúc của đặt phòng? Điều khoản hợp đồng nào chứng minh lựa chọn đó?","Trình bày cách tính RevPAR, phân biệt với ADR, và cách xử lý yêu cầu ghi nhận doanh thu của đặt phòng đã hủy."],en:["Why did you change the booking's segment code? Which contract term supports your choice?","Explain how you calculated RevPAR, how it differs from ADR, and how you handle a request to record revenue from a cancelled booking."]},hints:{vi:["Mở hợp đồng của đối tác và xem loại khách hàng, loại giá trước khi chọn mã phân khúc.","Theo SOP mục 3.2: xác định đúng mẫu số là đêm phòng sẵn có hay đêm phòng bán.","Đọc lại SOP mục 4.2: chỉ ghi nhận doanh thu khi dịch vụ đã cung cấp, mọi áp lực sửa số phải báo cáo."],en:["Open the partner contract and check the customer type and rate type before choosing a segment.","Per SOP 3.2: decide whether the denominator is available or sold room nights.","Re-read SOP 4.2: record revenue only for services delivered; escalate any pressure to change figures."]}},learning:{summary:{vi:"Chuyên viên kinh doanh, đặt phòng và phân tích doanh thu khách sạn, resort quản lý tồn phòng trên các kênh, kiểm soát đặt phòng theo hợp đồng, dự báo nhu cầu và đề xuất giá để tối đa hóa doanh thu. Công việc gồm phân tích pickup, nhịp đặt phòng, phân khúc thị trường, báo cáo công suất, ADR, RevPAR và đối chiếu số liệu với kế toán. Nghề đòi hỏi tư duy định lượng, hiểu hợp đồng phân phối và giữ số liệu trung thực trước áp lực chỉ tiêu.",en:"A hotel reservation and revenue analyst manages room inventory across channels, controls bookings against contracts, forecasts demand and recommends prices to maximise revenue. The work covers pickup and pace analysis, market segmentation, occupancy, ADR and RevPAR reporting and reconciliation with accounting. The role requires quantitative thinking, understanding of distribution contracts and honest numbers under target pressure."},responsibilities:{vi:["Kiểm tra, xác nhận đặt phòng và áp đúng mã giá, mã phân khúc theo hợp đồng.","Cập nhật giá, hạn mức phòng và điều kiện bán trên trình quản lý kênh.","Dự báo công suất, phân tích pickup, nhịp đặt phòng và giá của đối thủ.","Lập báo cáo công suất, ADR, RevPAR theo phân khúc và giải thích chênh lệch.","Đối chiếu doanh thu phòng, hoa hồng đối tác và trạng thái đặt phòng với kế toán."],en:["Check and confirm bookings with the correct rate and segment codes per contract.","Update rates, allocations and selling conditions in the channel manager.","Forecast occupancy and analyse pickup, booking pace and competitor rates.","Report occupancy, ADR and RevPAR by segment and explain variances.","Reconcile room revenue, partner commissions and booking status with accounting."]},competencies:[{name:{vi:"Phân tích chỉ số doanh thu",en:"Revenue metrics analysis"},desc:{vi:"Tính đúng công suất, ADR, RevPAR và hiểu tác động của từng thành phần.",en:"Compute occupancy, ADR and RevPAR correctly and understand each driver."}},{name:{vi:"Phân khúc thị trường",en:"Market segmentation"},desc:{vi:"Xếp đặt phòng đúng phân khúc theo loại khách và hợp đồng, giữ dữ liệu nhất quán.",en:"Code bookings by customer type and contract and keep data consistent."}},{name:{vi:"Dự báo & định giá",en:"Forecasting & pricing"},desc:{vi:"Đọc nhịp đặt phòng, sự kiện, giá đối thủ để đề xuất giá và hạn mức phù hợp.",en:"Read booking pace, events and competitor rates to recommend prices and limits."}},{name:{vi:"Kiểm soát hợp đồng phân phối",en:"Distribution contract control"},desc:{vi:"Theo dõi giá thuần, hoa hồng, chính sách hủy và tính chẵn giá giữa các kênh.",en:"Track net rates, commissions, cancellation policies and rate parity across channels."}},{name:{vi:"Liêm chính số liệu",en:"Data integrity"},desc:{vi:"Báo cáo đúng thực tế, ghi chú minh bạch và từ chối điều chỉnh số liệu sai.",en:"Report reality, annotate transparently and refuse to manipulate figures."}}],knowledge:{vi:["Chỉ số chuẩn ngành: công suất phòng, ADR, RevPAR, TRevPAR, GOPPAR và cách tính nhất quán.","Hệ thống báo cáo thống nhất ngành khách sạn (USALI) và nguyên tắc phân khúc thị trường.","Chuẩn mực kế toán Việt Nam VAS 14 về doanh thu: chỉ ghi nhận khi dịch vụ đã được cung cấp.","Nghị định 123/2020/NĐ-CP về hóa đơn, chứng từ khi xuất hóa đơn tiền phòng, tiền cọc.","Nguyên lý quản trị doanh thu: dự báo, định giá động, kiểm soát hạn mức và overbooking có kiểm soát."],en:["Industry metrics: occupancy, ADR, RevPAR, TRevPAR, GOPPAR and consistent calculation.","Uniform System of Accounts for the Lodging Industry (USALI) and market segmentation principles.","Vietnamese Accounting Standard VAS 14 on revenue: recognise only when the service is delivered.","Decree 123/2020/ND-CP on invoices for room charges and deposits.","Revenue management principles: forecasting, dynamic pricing, inventory controls and managed overbooking."]},tools:["Hệ thống quản trị doanh thu (RMS)","Phần mềm quản lý khách sạn (PMS)","Trình quản lý kênh bán phòng","Công cụ theo dõi giá đối thủ","Phần mềm phân tích dữ liệu"],kpis:{vi:["Chỉ số RevPAR so với nhóm khách sạn cạnh tranh.","Sai số dự báo công suất 30 ngày tới.","Tỷ lệ đặt phòng sai mã giá hoặc sai phân khúc (mục tiêu dưới 1%).","Tỷ trọng doanh thu kênh trực tiếp và chi phí phân phối."],en:["RevPAR index against the competitive set.","Forecast error for occupancy 30 days out.","Bookings with wrong rate or segment codes (target below 1%).","Direct channel revenue share and distribution cost."]},day:[{time:"08:30",vi:"Đọc báo cáo pickup đêm qua, kiểm tra đặt phòng mới và đặt phòng bị hủy.",en:"Read last night's pickup report and check new and cancelled bookings."},{time:"10:00",vi:"Điều chỉnh giá, hạn mức trên các kênh theo dự báo và giá đối thủ.",en:"Adjust rates and allocations across channels based on forecast and competitor rates."},{time:"13:30",vi:"Đối chiếu đặt phòng của đối tác với hợp đồng giá thuần và mã phân khúc.",en:"Match partner bookings with net rate contracts and segment codes."},{time:"15:30",vi:"Họp quản trị doanh thu với kinh doanh, tiền sảnh, tài chính.",en:"Hold the revenue meeting with sales, front office and finance."},{time:"17:00",vi:"Hoàn thiện báo cáo chỉ số ngày và ghi chú các chênh lệch bất thường.",en:"Finish the daily KPI report and note unusual variances."}],mistakes:{vi:["Xếp phân khúc theo kênh kỹ thuật thay vì theo loại khách hàng và hợp đồng.","Tính RevPAR bằng doanh thu chia số đêm phòng bán, nhầm với ADR.","Ghi nhận doanh thu của đặt phòng đã hủy hoặc chưa phát sinh để đạt chỉ tiêu."],en:["Coding segments by technical channel instead of customer type and contract.","Computing RevPAR as revenue over rooms sold, confusing it with ADR.","Recording revenue from cancelled or future bookings to hit targets."]},career:[{vi:"Nhân viên đặt phòng",en:"Reservations agent"},{vi:"Chuyên viên đặt phòng và phân tích doanh thu",en:"Reservation and revenue analyst"},{vi:"Quản lý doanh thu khách sạn",en:"Hotel revenue manager"},{vi:"Giám đốc Quản trị Doanh thu cụm khách sạn",en:"Cluster director of revenue management"}],glossary:[{term:"ADR",vi:"Giá phòng bình quân: doanh thu phòng chia số đêm phòng bán có thu.",en:"Average daily rate: room revenue divided by paid room nights."},{term:"RevPAR",vi:"Doanh thu trên mỗi phòng sẵn có, bằng doanh thu phòng chia tổng đêm phòng sẵn có.",en:"Revenue per available room: room revenue divided by total available room nights."},{term:"Pickup",vi:"Số đêm phòng mới được đặt thêm trong một khoảng thời gian cho một ngày lưu trú.",en:"New room nights booked over a period for a given stay date."},{term:"Overbooking",vi:"Bán vượt số phòng có thật dựa trên dự báo hủy và vắng mặt, cần kiểm soát chặt.",en:"Selling beyond physical capacity based on forecast cancellations and no-shows, tightly controlled."},{term:"Market segment",vi:"Nhóm khách hàng có hành vi đặt phòng và loại giá tương đồng, như khách lẻ, công ty, lữ hành.",en:"Group of customers with similar booking behaviour and rate type, such as transient, corporate or wholesale."}],quiz:[{q:{vi:"Khách sạn 80 phòng, tháng 30 ngày, doanh thu phòng 3.600.000.000 đồng. RevPAR là bao nhiêu?",en:"An 80-room hotel, 30-day month, room revenue 3,600,000,000 VND. What is RevPAR?"},options:{vi:["1.800.000 đồng","2.000.000 đồng","1.200.000 đồng","1.500.000 đồng"],en:["1,800,000 VND","2,000,000 VND","1,200,000 VND","1,500,000 VND"]},answer:3,explain:{vi:"Tổng đêm phòng sẵn có = 80 x 30 = 2400; RevPAR = 3.600.000.000 / 2400 = 1.500.000 đồng.",en:"Available room nights = 80 x 30 = 2400; RevPAR = 3,600,000,000 / 2400 = 1,500,000 VND."}},{q:{vi:"Công thức nào tương đương với RevPAR?",en:"Which formula is equivalent to RevPAR?"},options:{vi:["ADR x công suất phòng","ADR chia công suất phòng","Doanh thu chia số phòng bán","ADR cộng công suất phòng"],en:["ADR x occupancy","ADR divided by occupancy","Revenue divided by rooms sold","ADR plus occupancy"]},answer:0,explain:{vi:"RevPAR = ADR x công suất phòng khi dùng cùng mẫu số đêm phòng sẵn có và cùng định nghĩa phòng bán.",en:"RevPAR = ADR x occupancy when both use the same available nights and the same definition of rooms sold."}},{q:{vi:"Cấp trên yêu cầu ghi nhận doanh thu của đoàn đã hủy để đạt chỉ tiêu tháng. Bạn làm gì?",en:"Your boss asks you to record revenue from a cancelled group to meet the monthly target. What do you do?"},options:{vi:["Làm theo rồi điều chỉnh sau","Ghi nhận một nửa","Từ chối, giữ số liệu đúng và báo lãnh đạo có thẩm quyền","Xóa đặt phòng khỏi hệ thống"],en:["Comply and reverse later","Record half of it","Refuse, keep the true figures and escalate to the proper authority","Delete the booking from the system"]},answer:2,explain:{vi:"Ghi nhận doanh thu chưa phát sinh làm sai lệch báo cáo tài chính; phải giữ số liệu trung thực và báo cáo áp lực.",en:"Recording revenue that did not occur misstates financial reports; keep honest figures and escalate the pressure."}},{q:{vi:"Đặt phòng của công ty lữ hành theo hợp đồng giá thuần cố định thường thuộc phân khúc nào?",en:"A tour operator booking under a fixed net rate contract usually belongs to which segment?"},options:{vi:["OTA","Wholesale","Corporate","Walk-in"],en:["OTA","Wholesale","Corporate","Walk-in"]},answer:1,explain:{vi:"Đối tác lữ hành mua giá thuần để đóng gói bán lại thuộc phân khúc wholesale, dù đặt phòng đi qua kênh nào.",en:"Tour operators buying net rates to package and resell are wholesale, whatever channel the booking uses."}}],tools_en:["Revenue management system (RMS)","Hotel property management system (PMS)","Channel manager","Competitor rate shopping tool","Data analytics software"]}}})})(window.KKR);
